using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.UI;using Object=UnityEngine.Object;
[InitializeOnLoad]public static class HollowChecks{
 static bool boot;static string report="";static HollowChecks(){if(SessionState.GetBool("HollowChecks",false))EditorApplication.update+=Boot;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/HollowGreenpath.unity");SessionState.SetBool("HollowChecks",true);Physics2D.simulationMode=SimulationMode2D.FixedUpdate;EditorApplication.isPlaying=true;}
 static void Boot(){EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying||boot||Time.frameCount<3)return;boot=true;Application.logMessageReceived+=Log;new GameObject("Hollow checks").AddComponent<HollowCheckRunner>().StartCoroutine("Run");}
 static void Log(string m,string st,LogType t){if((t==LogType.Error||t==LogType.Exception)&&!st.Contains("UnityEditor.Search"))Done(1,m+st);}
 public static void Need(bool b,string m){if(!b)throw new Exception(m);report+="PASS "+m+"\n";File.WriteAllText("hollow-checks.txt",report);}
 public static void Done(int code,string m=""){SessionState.SetBool("HollowChecks",false);File.WriteAllText("hollow-checks.txt",report+m);EditorApplication.Exit(code);}
}
public class HollowCheckRunner:MonoBehaviour {
 static void Need(bool b,string m)=>HollowChecks.Need(b,m);DemoSession s;HollowJourney journey;Rigidbody2D rb;
 void Place(Vector3 p){journey.Teleport(p);rb.constraints=RigidbodyConstraints2D.FreezeAll;s.GetComponent<PlayerMovement>().enabled=false;}
 IEnumerator Run(){s=DemoSession.Instance;journey=Object.FindAnyObjectByType<HollowJourney>();rb=s.GetComponent<Rigidbody2D>();Need(journey.rooms.Length==3,"Three imported rooms exist");Need(AssetDatabase.GetAssetPath(s.GetComponent<SpriteRenderer>().sprite).Contains("Hollow/player"),"Knight replaces Red artwork");s.Begin();yield return new WaitForSeconds(1);Need(s.transform.position.y>0,"Starting spawn stays in map");yield return new WaitForSeconds(2);Capture("hollow-entry.png");
 var actors=Object.FindObjectsByType<DimensionActor>(FindObjectsInactive.Include);Need(actors.Count(a=>a.content.GetComponent<HollowEnemy>()!=null)>=6,"Both new enemy species are present");
 foreach(var a in actors){if(a.content==null)continue;var ai=a.content.GetComponent<HollowEnemy>();if(ai==null)continue;Need(a.dimension==(ai.flying?0:1),"Enemy assigned to its world: "+a.name);}
 var dim=s.GetComponent<DimensionController>();dim.SetDimension(0);yield return null;Need(actors.Where(a=>a.dimension==1).All(a=>!a.content.activeSelf),"Echo enemies disappear in Frost");dim.SetDimension(1);yield return null;Need(actors.Where(a=>a.dimension==0).All(a=>!a.content.activeSelf),"Frost enemies disappear in Echo");
 var fly=actors.First(a=>a.dimension==0);dim.SetDimension(0);var fh=fly.content.GetComponent<EnemyHealth>();int before=fh.CurrentHealth;fh.TakeDamage(1,s.transform.position,0);dim.SetDimension(1);dim.SetDimension(0);Need(fh.CurrentHealth==before-1,"Enemy damage persists across world changes");
 var key=Object.FindObjectsByType<QuestInteractable>().First(q=>q.kind==QuestInteractable.Kind.EchoKey);var spirit=Object.FindObjectsByType<QuestInteractable>().First(q=>q.kind==QuestInteractable.Kind.Spirit);var doors=Object.FindObjectsByType<HollowDoor>();var locked=doors.First(d=>d.needsKey);dim.SetDimension(0);Place(locked.transform.position+Vector3.up*.6f);Need(!locked.TryEnter(s),"Frost passage rejects entry without violet key");Place(key.transform.position);yield return null;Need(!s.HasEchoKey,"Key cannot be collected in Frost");dim.SetDimension(1);yield return null;Need(s.HasEchoKey,"Key collected only in Echo");Place(locked.transform.position+Vector3.up*.6f);Need(!locked.TryEnter(s),"Key alone cannot open passage in Echo");dim.SetDimension(0);Need(locked.TryEnter(s),"Key opens passage in Frost");yield return new WaitForSeconds(.1f);Need(journey.CurrentRoom==1,"Passage reaches second room");yield return new WaitForSeconds(2.2f);Capture("hollow-grove.png");
 var sanctum=doors.First(d=>d.needsSpirit);Place(sanctum.transform.position+Vector3.up*.6f);Need(!sanctum.TryEnter(s),"Sanctum requires Spirit Bolt");Place(spirit.transform.position);dim.SetDimension(1);yield return null;Need(s.HasSpirit,"Spirit reward unlocks cast");dim.SetDimension(0);Place(sanctum.transform.position+Vector3.up*.6f);Need(sanctum.TryEnter(s),"Spirit opens sanctum route");yield return null;Need(journey.CurrentRoom==2,"Third room transition works");yield return new WaitForSeconds(2.2f);Capture("hollow-sanctum.png");
 var enemy=actors.First(a=>a.dimension==1).content;dim.SetDimension(1);Place(enemy.transform.position+Vector3.right*3);var horn=enemy.GetComponent<HollowEnemy>();yield return new WaitForSeconds(.3f);Need(horn.State==HollowEnemy.Mode.Warning,"Hornhead warns before charging");yield return new WaitForSeconds(.6f);Need(horn.Attacks>0,"Hornhead performs a committed charge");
 dim.SetDimension(0);Place(fly.content.transform.position+new Vector3(3,2));yield return new WaitForSeconds(1);Need(fly.content.GetComponent<HollowEnemy>().Attacks>0,"Mossfly emerges and pursues");Need(fly.content.GetComponent<Rigidbody2D>().gravityScale==0,"Mossfly remains airborne");
 var old=rb.position;s.GetComponent<RunProgress>().Respawn();Need((rb.position-old).magnitude>1,"Checkpoint return leaves remote enemy test position");yield return s.BossPractice();yield return null;Need(journey.CurrentRoom==2&&s.HasSpirit&&s.GetComponent<PlayerHealth>().currentHealth==100,"Boss shortcut reaches the Hollow arena with full health and cast");HollowChecks.Done(0);}
 void Capture(string name){var cam=Camera.main;cam.GetComponent<HollowRoomCamera>().Snap();cam.SendMessage("LateUpdate");var canvas=Object.FindObjectsByType<Canvas>().First(c=>c.name=="Dimension HUD");canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;var rt=new RenderTexture(1600,900,24);rt.Create();cam.aspect=1600f/900;cam.targetTexture=rt;canvas.GetComponent<CanvasScaler>().SendMessage("Handle");Canvas.ForceUpdateCanvases();RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes(name,t.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;rt.Release();Object.Destroy(rt);Object.Destroy(t);canvas.renderMode=RenderMode.ScreenSpaceOverlay;}
}
